import sys
import math

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    small_divisors = []
    large_divisors = []
    limit = int(math.isqrt(n))

    for i in range(1, limit + 1):
        if n % i == 0:
            small_divisors.append(i)
            if i != n // i:
                large_divisors.append(n // i)

    # large_divisors are in descending order, so reverse to get ascending
    large_divisors.reverse()

    all_divisors = small_divisors + large_divisors

    if k > len(all_divisors):
        print(-1)
    else:
        print(all_divisors[k - 1])

if __name__ == "__main__":
    solve()

